+type StdoutSnapshot = (
+    rustix::fs::OFlags,
+    rustix::fs::OFlags,
+    (Duration, Duration),
+    Result<Vec<u8>, rustix::io::Errno>,
+);
+
+// A timeout diagnostic only: never wait for bytes or EOF from a live child.
+fn stdout_now(stdout: &impl std::os::fd::AsFd, since: Instant) -> io::Result<StdoutSnapshot> {
+    let before = rustix::fs::fcntl_getfl(stdout)?;
+    rustix::fs::fcntl_setfl(stdout, before | rustix::fs::OFlags::NONBLOCK)?;
+    let after = rustix::fs::fcntl_getfl(stdout)?;
+    if !after.contains(rustix::fs::OFlags::NONBLOCK) {
+        return Err(io::Error::other("stdout remained blocking"));
+    }
+    let mut buffer = [0_u8; 128];
+    let read_started = since.elapsed();
+    let read = rustix::io::read(stdout, &mut buffer).map(|count| buffer[..count].to_vec());
+    let read_finished = since.elapsed();
+    Ok((before, after, (read_started, read_finished), read))
 }

